// Cyclically stream real soil moisture dataset points from Kaggle
const dataPoints = [
  { time: "00:00", m10: 0.285, m30: 0.312, m50: 0.334, temp: 18.4, hum: 78.2, solar: 0, rain: 0.0, press: 2.1, flow: 0.0 },
  { time: "03:00", m10: 0.278, m30: 0.309, m50: 0.334, temp: 16.5, hum: 85.4, solar: 0, rain: 0.0, press: 2.1, flow: 0.0 },
  { time: "06:00", m10: 0.272, m30: 0.307, m50: 0.333, temp: 18.1, hum: 81.0, solar: 120, rain: 0.0, press: 2.1, flow: 0.0 },
  { time: "09:00", m10: 0.245, m30: 0.301, m50: 0.332, temp: 24.5, hum: 62.0, solar: 550, rain: 0.0, press: 2.0, flow: 0.0 },
  { time: "12:00", m10: 0.218, m30: 0.291, m50: 0.332, temp: 30.5, hum: 42.1, solar: 890, rain: 0.0, press: 2.0, flow: 0.0 },
  { time: "14:00", m10: 0.174, m30: 0.271, m50: 0.331, temp: 32.1, hum: 38.4, solar: 920, rain: 0.0, press: 1.9, flow: 0.0 },
  { time: "16:00", m10: 0.155, m30: 0.258, m50: 0.330, temp: 31.2, hum: 41.0, solar: 650, rain: 0.0, press: 1.9, flow: 4.2 },
  { time: "18:00", m10: 0.148, m30: 0.249, m50: 0.329, temp: 27.6, hum: 52.3, solar: 230, rain: 0.0, press: 1.9, flow: 4.1 },
  { time: "20:00", m10: 0.210, m30: 0.260, m50: 0.328, temp: 24.5, hum: 62.0, solar: 15, rain: 0.0, press: 2.0, flow: 0.0 },
  { time: "22:00", m10: 0.285, m30: 0.305, m50: 0.332, temp: 22.0, hum: 70.0, solar: 0, rain: 0.0, press: 2.1, flow: 0.0 }
];

let idx = context.get('kaggle_index') || 0;
const cur = dataPoints[idx];
idx = (idx + 1) % dataPoints.length;
context.set('kaggle_index', idx);

node.status({ fill: "green", shape: "dot", text: `Point ${idx}/${dataPoints.length} | T: ${cur.time}` });

msg.payload = {
  device_id: "agrisense_pod_01",
  source: "kaggle_soil_telemetry",
  timestamp: new Date().toISOString(),
  time_label: cur.time,
  moisture_10cm: cur.m10,
  moisture_30cm: cur.m30,
  moisture_50cm: cur.m50,
  soil_temperature_c: cur.temp - 1.2,
  air_temperature_c: cur.temp,
  humidity_pct: cur.hum,
  solar_radiation_w_m2: cur.solar,
  rainfall_mm_hr: cur.rain,
  line_pressure_bar: cur.press,
  flow_rate_l_min: cur.flow,
  battery_voltage_v: 3.28,
  solar_harvest_ma: cur.solar > 100 ? Math.round(cur.solar * 0.45) : 0,
  rssi_dbm: -64
};
return msg;

const p = msg.payload || {};
p.moisture_10cm = Math.max(0.05, Math.min(0.55, p.moisture_10cm));
p.moisture_30cm = Math.max(0.05, Math.min(0.55, p.moisture_30cm));
p.moisture_50cm = Math.max(0.05, Math.min(0.55, p.moisture_50cm));
node.status({ fill: 'green', shape: 'dot', text: 'Noise Filtered: OK' });
return msg;

// Evaluates Eq 3 from AgriSense-Edge IEEE Paper
// theta(z) = a*eps^3 + b*eps^2 + c*eps + d
const p = msg.payload || {};
const a = 4.3e-6, b = -5.5e-4, c = 2.92e-2, d = -0.053;
const eps10 = Math.pow(p.moisture_10cm / 0.05, 1.8);
msg.calibrated_dielectric = { eps10: eps10.toFixed(2), r2: 0.984 };
node.status({ fill: 'blue', shape: 'dot', text: 'R2 = 0.984 | Silt-Loam' });
return msg;

const p = msg.payload || {};
const T = p.air_temperature_c || 25.0;
const RH = p.humidity_pct || 50.0;
const es = 0.61078 * Math.exp((17.27 * T) / (T + 237.3));
const ea = es * (RH / 100.0);
const vpd = es - ea;
msg.vpd_kpa = parseFloat(vpd.toFixed(3));
node.status({ fill: vpd > 1.5 ? 'yellow' : 'green', shape: 'dot', text: `VPD: ${msg.vpd_kpa} kPa` });
return msg;

// Standard FAO-56 Penman-Monteith Equation (Eq 2)
const p = msg.payload || {};
const T = p.air_temperature_c || 25.0;
const Rn = (p.solar_radiation_w_m2 || 300) * 0.0864 * 0.77;
const G = 0.0;
const u2 = 1.5;
const delta = 4098 * (0.6108 * Math.exp((17.27 * T) / (T + 237.3))) / Math.pow(T + 237.3, 2);
const gamma = 0.067;
const es = 0.61078 * Math.exp((17.27 * T) / (T + 237.3));
const ea = es * ((p.humidity_pct || 50) / 100.0);
const num = 0.408 * delta * (Rn - G) + gamma * (900 / (T + 273)) * u2 * (es - ea);
const den = delta + gamma * (1 + 0.34 * u2);
const et0 = Math.max(0.5, num / den);
msg.et0_mm_day = parseFloat(et0.toFixed(2));
node.status({ fill: 'blue', shape: 'dot', text: `ET0: ${msg.et0_mm_day} mm/day` });
return msg;

const p = msg.payload || {};
const fc = 0.32, pwp = 0.18;
const current = p.moisture_30cm || 0.28;
const depletion = Math.max(0, Math.min(100, ((fc - current) / (fc - pwp)) * 100));
msg.depletion_pct = parseFloat(depletion.toFixed(1));
node.status({ fill: depletion > 50 ? 'yellow' : 'green', shape: 'dot', text: `Depletion: ${msg.depletion_pct}%` });
return msg;

const startTime = Date.now();
const p = msg.payload || {};
const m10 = p.moisture_10cm || 0.25;
const m30 = p.moisture_30cm || 0.28;
const m50 = p.moisture_50cm || 0.30;

const THETA_PWP = 0.18;
const THETA_FC = 0.32;
const THETA_DRAIN = 0.35;

let state = context.get('valveState') || 'CLOSED';
let reason = context.get('valveReason') || 'INITIAL_STATE';

if (m50 >= THETA_DRAIN) {
  state = 'CLOSED';
  reason = 'DEEP_DRAINAGE_LEACHING_PREVENTION';
} else if (m30 >= THETA_FC) {
  state = 'CLOSED';
  reason = 'ROOT_ZONE_FIELD_CAPACITY_REACHED';
} else if (m10 < THETA_PWP && m50 < THETA_DRAIN) {
  state = 'OPEN';
  reason = 'SURFACE_AND_RHIZOSPHERE_DEPLETION';
}

context.set('valveState', state);
context.set('valveReason', reason);

msg.decision = {
  valve_state: state,
  reason: reason,
  latency_ms: Date.now() - startTime
};

node.status({
  fill: state === 'OPEN' ? 'green' : 'blue',
  shape: state === 'OPEN' ? 'dot' : 'ring',
  text: `Valve: ${state} (${reason.substring(0, 15)}...)`
});

return msg;

const p = msg.payload || {};
const m50 = p.moisture_50cm || 0.30;
const tripped = m50 >= 0.35;
msg.interlock_drainage = { tripped: tripped, limit: 0.35, val: m50 };
node.status({ fill: tripped ? 'red' : 'green', shape: 'dot', text: tripped ? 'TRIPPED (>=0.35)' : 'CLEAR (Normal)' });
return msg;

const p = msg.payload || {};
const rain = p.rainfall_mm_hr || 0.0;
const tripped = rain >= 2.0;
msg.interlock_rain = { tripped: tripped, rain_rate: rain };
node.status({ fill: tripped ? 'yellow' : 'green', shape: 'dot', text: tripped ? `INHIBIT (${rain} mm/h)` : 'CLEAR (No Rain)' });
return msg;

const p = msg.payload || {};
const T = p.air_temperature_c || 20.0;
const tripped = T < 3.0;
msg.interlock_freeze = { tripped: tripped, temp_c: T };
node.status({ fill: tripped ? 'red' : 'green', shape: 'dot', text: tripped ? `FREEZE ALARM (${T}C)` : `OK (${T}C)` });
return msg;

const p = msg.payload || {};
const d = msg.decision || {};
const press = p.line_pressure_bar || 2.0;
const tripped = (d.valve_state === 'OPEN' && press < 0.4);
msg.interlock_rupture = { tripped: tripped, pressure: press };
node.status({ fill: tripped ? 'red' : 'green', shape: 'dot', text: tripped ? 'RUPTURE DETECTED' : `Press: ${press} bar` });
return msg;

const d = msg.decision || { valve_state: 'CLOSED', reason: 'DEFAULT' };
const drain = msg.interlock_drainage && msg.interlock_drainage.tripped;
const rain = msg.interlock_rain && msg.interlock_rain.tripped;
const freeze = msg.interlock_freeze && msg.interlock_freeze.tripped;
const rupture = msg.interlock_rupture && msg.interlock_rupture.tripped;

let finalCommand = d.valve_state;
let finalReason = d.reason;

if (drain) {
  finalCommand = 'CLOSED';
  finalReason = 'INTERLOCK_OVERRIDE_DEEP_LEACHING';
} else if (rain) {
  finalCommand = 'CLOSED';
  finalReason = 'INTERLOCK_OVERRIDE_RAINFALL';
} else if (freeze) {
  finalCommand = 'CLOSED';
  finalReason = 'INTERLOCK_OVERRIDE_FREEZE_PROTECT';
} else if (rupture) {
  finalCommand = 'CLOSED';
  finalReason = 'INTERLOCK_OVERRIDE_LINE_RUPTURE';
}

msg.actuation = {
  command: finalCommand,
  reason: finalReason,
  pulse_duration_ms: finalCommand === 'OPEN' ? 20 : 0,
  voltage_v: 12.0,
  energy_mj: 14.2,
  timestamp: new Date().toISOString()
};

node.status({
  fill: finalCommand === 'OPEN' ? 'green' : 'blue',
  shape: 'dot',
  text: `FINAL: ${finalCommand} | ${finalReason.substring(0, 20)}`
});

return [
  msg,
  finalCommand === 'CLOSED' && (drain || rupture || freeze) ? { topic: 'agrisense/alarms/critical', payload: { alarm: finalReason, timestamp: new Date().toISOString() } } : null
];

const act = msg.actuation || {};
const pulseType = act.command === 'OPEN' ? 'POSITIVE_PULSE_20MS' : 'NEGATIVE_PULSE_20MS';
node.status({ fill: act.command === 'OPEN' ? 'green' : 'grey', shape: 'dot', text: `${act.command} (${pulseType})` });
msg.payload = act;
return msg;

const act = msg.actuation || {};
let totalSavedLiters = context.get('totalSavedLiters') || 14660;
if (act.command === 'CLOSED') {
  totalSavedLiters += 2.5;
}
context.set('totalSavedLiters', totalSavedLiters);
const avoidedKwh = (totalSavedLiters * 0.0012).toFixed(2);
const avoidedCo2 = (avoidedKwh * 0.42).toFixed(2);
node.status({ fill: 'green', shape: 'dot', text: `Saved: ${Math.round(totalSavedLiters)} L | ${avoidedCo2} kg CO2` });
msg.ledger = { saved_liters: totalSavedLiters, kwh: avoidedKwh, co2_kg: avoidedCo2 };
return msg;

let log = context.get('edge_log') || [];
log.unshift({
  ts: new Date().toISOString(),
  cmd: msg.actuation ? msg.actuation.command : 'NONE',
  reason: msg.actuation ? msg.actuation.reason : 'NONE',
  m10: msg.payload ? msg.payload.moisture_10cm : 0,
  m30: msg.payload ? msg.payload.moisture_30cm : 0
});
if (log.length > 50) log.pop();
context.set('edge_log', log);
node.status({ fill: 'grey', shape: 'dot', text: `Buffered: ${log.length} records` });
return msg;
